method how_many_times(string: string, substring: string) returns (count: int)
    requires substring != ""
    ensures count >= 0
    ensures count == CountOccurrences(string, substring)

    // Helper function to count occurrences of substring in string
    function CountOccurrences(s: string, sub: string): int
        reads s, sub
        // Count the number of times sub appears in s, including overlapping occurrences
        decreases |s|
    {
        if |s| < |sub| {
            return 0;
        }
        if s[..|sub|] == sub {
            return 1 + CountOccurrences(s[1..], sub);
        } else {
            return CountOccurrences(s[1..], sub);
        }
    }
